",26.841796875,7.865625000000001],["L",23.466796875,7.865625000000001],["L",23.466796875,-5.341406249999999],["L",19.412109375,-4.052343749999999],["L",19.412109375,-6.712499999999999],["L",26.478515625,-9.232031249999999],["L",26.841796875,-9.232031249999999],["Z"]],"fitScale":1,"clip":{"height":100,"width":234.9306640625,"x":-117.46533203125,"y":-50},"advanceBounds":{"width":62.42578125,"height":28.799999999999997}}},"numberSymbols":{}}$prepared$::jsonb;
  reference eshop.blueprints; b eshop.blueprints; item jsonb;
  profile jsonb; next_layout jsonb; ids text[]; receipt jsonb;
BEGIN
  PERFORM public.lock_blueprint_scope_internal(ARRAY[81::bigint,100::bigint,1072585::bigint]);
  SELECT * INTO STRICT reference FROM eshop.blueprints
    WHERE id=87 AND occasion=1072585 AND organization=3 FOR SHARE;
  IF reference.layout_revision<>4 OR
    encode(extensions.digest(convert_to(reference.layout::text,'UTF8'),'sha256'),'hex')<>'93c5755ea595dad3c18ea2095add12d69c1c89636152bdd178becc6bd9894af5'
  THEN RAISE EXCEPTION 'AKH2026 reference changed since review'; END IF;
  profile:=jsonb_build_object('fontFamilyId',reference.layout#>'{styles,kinds,table,label,fontFamilyId}',
    'weight',reference.layout#>'{styles,kinds,table,label,weight}',
    'italic',reference.layout#>'{styles,kinds,table,label,italic}');
  IF profile->>'weight'<>'700' THEN RAISE EXCEPTION 'Expected genuine bold face'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(reviewed) LOOP
    SELECT * INTO STRICT b FROM eshop.blueprints WHERE id=(item->>'id')::bigint
      AND occasion=(item->>'occasion')::bigint AND organization=3 FOR UPDATE;
    IF b.layout_revision<>(item->>'layout_revision')::bigint OR
      encode(extensions.digest(convert_to(b.layout::text,'UTF8'),'sha256'),'hex')
        IS DISTINCT FROM item->>'layout_sha256'
    THEN RAISE EXCEPTION 'Blueprint % changed since review',b.id; END IF;
    next_layout:=jsonb_set(b.layout,'{styles,kinds,table,label}',
      (b.layout#>'{styles,kinds,table,label}')||profile);
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(b.layout->'nodes') old_node
      JOIN jsonb_array_elements(next_layout->'nodes') new_node ON old_node->>'id'=new_node->>'id'
      WHERE CASE WHEN old_node->>'kind'='table' THEN
        (public.blueprint_resolved_label_internal(b.layout,old_node)-ARRAY['fontFamilyId','weight','italic'])
          IS DISTINCT FROM (public.blueprint_resolved_label_internal(next_layout,new_node)-ARRAY['fontFamilyId','weight','italic'])
        OR NOT (public.blueprint_resolved_label_internal(next_layout,new_node) @> profile)
      ELSE public.blueprint_resolved_label_internal(b.layout,old_node)
        IS DISTINCT FROM public.blueprint_resolved_label_internal(next_layout,new_node) END)
    THEN RAISE EXCEPTION 'Blueprint % changed unrelated label properties',b.id; END IF;
    PERFORM public.validate_blueprint_layout_internal(next_layout);
    -- Reuse exact immutable descriptors through the canonical scope-copy owner.
    PERFORM public.copy_blueprint_text_resources_internal(reference.occasion,NULL,b.occasion,next_layout);
    IF b.id=32 THEN
      IF EXISTS(SELECT 1 FROM jsonb_each(prepared->'textLayouts') t
        WHERE NOT EXISTS(SELECT 1 FROM public.blueprint_layout_text_requests_internal(next_layout,true) q
          WHERE q.descriptor=t.value->'descriptor'))
      THEN RAISE EXCEPTION 'Prepared resources outside requested layout'; END IF;
      PERFORM public.register_blueprint_text_resources(b.occasion,NULL,prepared);
    END IF;
    PERFORM public.check_blueprint_text_resources_internal(next_layout,b.occasion);
    ids:=public.blueprint_text_resource_ids_internal(next_layout,b.occasion);
    UPDATE eshop.blueprints SET layout=next_layout,layout_text_resource_ids=ids,
      layout_revision=layout_revision+1,updated_at=now() WHERE id=b.id;
    receipt:=public.record_client_sync_commit_v1(b.occasion,
      'inventory.blueprint.akh_bold_alignment','inventory',
      jsonb_build_array(jsonb_build_object('entityType','blueprint','entityId',b.id::text,
        'operation','update','safeLabel',b.title,'changedFields',jsonb_build_array('layout','layout_text_resource_ids'))),
      '{}'::text[],'[]'::jsonb,'[]'::jsonb,'service',
      'User requested older AKH plans match AKH2026 Roboto Bold; preserve custom sizes');
    RAISE NOTICE 'Blueprint %, revision %, commit %',b.id,b.layout_revision+1,receipt->>'commitId';
  END LOOP;
END $$;
COMMIT;
